const regionalPDFs={"Vale dos Sinos 2": {"file": "Diagnostico_Vale_dos_Sinos_2_3tri2026.pdf", "data": ""}, "Serra 2": {"file": "Diagnostico_Serra_2_3tri2026.pdf", "data": ""}, "Vale do Taquari 1": {"file": "Diagnostico_Vale_do_Taquari_1_3tri2026.pdf", "data": ""}, "Vale dos Sinos 1": {"file": "Diagnostico_Vale_dos_Sinos_1_3tri2026.pdf", "data": ""}, "Serra 3": {"file": "Diagnostico_Serra_3_3tri2026.pdf", "data": ""}, "Serra 1": {"file": "Diagnostico_Serra_1_3tri2026.pdf", "data": ""}, "Metropolitana 2": {"file": "Diagnostico_Metropolitana_2_3tri2026.pdf", "data": ""}, "Vale dos Sinos 3": {"file": "Diagnostico_Vale_dos_Sinos_3_3tri2026.pdf", "data": ""}, "Norte 2": {"file": "Diagnostico_Norte_2_3tri2026.pdf", "data": ""}, "Encosta da Serra": {"file": "Diagnostico_Encosta_da_Serra_3tri2026.pdf", "data": ""}, "Sul": {"file": "Diagnostico_Sul_3tri2026.pdf", "data": ""}, "Noroeste 2": {"file": "Diagnostico_Noroeste_2_3tri2026.pdf", "data": ""}, "Vale do Rio Pardo": {"file": "Diagnostico_Vale_do_Rio_Pardo_3tri2026.pdf", "data": ""}, "Vale do Taquari 2": {"file": "Diagnostico_Vale_do_Taquari_2_3tri2026.pdf", "data": ""}, "Metropolitana 3": {"file": "Diagnostico_Metropolitana_3_3tri2026.pdf", "data": ""}, "Noroeste 1": {"file": "Diagnostico_Noroeste_1_3tri2026.pdf", "data": ""}, "Norte 1": {"file": "Diagnostico_Norte_1_3tri2026.pdf", "data": ""}, "Metropolitana 1": {"file": "Diagnostico_Metropolitana_1_3tri2026.pdf", "data": ""}, "Central": {"file": "Diagnostico_Central_3tri2026.pdf", "data": ""}};
exportPdf=function(){const p=regionalPDFs[document.getElementById("regionSelect").value];if(!p)return;const b=Uint8Array.from(atob(p.data),c=>c.charCodeAt(0));const url=URL.createObjectURL(new Blob([b],{type:"application/pdf"}));const a=document.createElement("a");a.href=url;a.download=p.file;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)};
